# NOTE: Assertions have been autogenerated by utils/update_mca_test_checks.py
# RUN: llvm-mca -mtriple=aarch64-none-linux-gnu -mcpu=cortex-a53 -mattr=+fullfp16 -iterations=100 -resource-pressure=false -timeline=false -instruction-info=false < %s | FileCheck %s

# The FP/ASIMD issue restrictions of the Cortex-A53. All the operands are
# independent, so only the issue rate is limited. Measured on hardware, in
# cycles per operation:
#
#   fadd + fadd                         0.5
#   fcmp + fcmp                         1
#   fcmp + fadd                         0.5
#   fmul by-element + fmul by-element   1
#   fadd + fmul by-element              0.5
#   fcmp + fmul by-element              0.5
#   fcmp + fadd + fadd                  0.67
#   fmul by-element + fadd + fadd       0.67
#   Q-form + by-element Q-form          1
#   Q-form fadd + scalar fmul           1
#   Q-form fmul + scalar fadd           1
#   Q-form fmul + fcmp                  1
#   fdiv + 8 fmul                       the fmuls fit within the fdiv occupancy
#
# A Q-form takes the two-unit lane resource twice, which gives the right
# throughput on its own, but llvm-mca does not make it hold both lanes in the
# same cycle: the mixed Q-form + scalar regions below report 1.5 cycles per
# pair where hardware takes 2.

# LLVM-MCA-BEGIN fadd-fadd
fadd s16, s1, s2
fadd s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fcmp-fcmp
fcmp s1, s2
fcmp s3, s4
# LLVM-MCA-END

# LLVM-MCA-BEGIN fcmp-fadd
fcmp s1, s2
fadd s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulidx-fmulidx
fmul s16, s1, v2.s[1]
fmul s17, s1, v2.s[1]
# LLVM-MCA-END

# LLVM-MCA-BEGIN fadd-fmulidx
fadd s16, s1, s2
fmul s17, s1, v2.s[1]
# LLVM-MCA-END

# LLVM-MCA-BEGIN fcmp-fmulidx
fcmp s1, s2
fmul s17, s1, v2.s[1]
# LLVM-MCA-END

# LLVM-MCA-BEGIN fcmp-fadd-fadd
fcmp s1, s2
fadd s16, s1, s2
fadd s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulidx-fadd-fadd
fmul s16, s1, v2.s[1]
fadd s17, s1, s2
fadd s18, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmlaidx-fmlaidx
fmla v16.2s, v1.2s, v2.s[1]
fmla v17.2s, v1.2s, v2.s[1]
# LLVM-MCA-END

# LLVM-MCA-BEGIN faddq-fmul
fadd v16.4s, v1.4s, v2.4s
fmul s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulq-fadd
fmul v16.4s, v1.4s, v2.4s
fadd s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulq-fcmp
fmul v16.4s, v1.4s, v2.4s
fcmp s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulidxq-fadd
fmul v16.4s, v1.4s, v2.s[1]
fadd s17, s1, s2
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmulidxq-fmulidxq
fmul v16.4s, v1.4s, v2.s[1]
fmul v17.4s, v1.4s, v2.s[1]
# LLVM-MCA-END

# LLVM-MCA-BEGIN fdiv-fmul
fdiv s0, s1, s2
fmul s16, s1, s2
fmul s17, s1, s2
fmul s18, s1, s2
fmul s19, s1, s2
fmul s20, s1, s2
fmul s21, s1, s2
fmul s22, s1, s2
fmul s23, s1, s2
# LLVM-MCA-END

